"use client";
/**
 * RiderRush: EAT60 endless delivery runner through Ballia.
 *
 * Usage:
 *   <div style={{height:"100dvh"}}>
 *     <RiderRush onGameEnd={(r)=>saveToServer(r)} />
 *   </div>
 *
 * Props
 *   onGameEnd(result)  {score, distance, xp, coins, note, totals:{xp,coins}}  called on every crash.
 *                      Save it to your backend and VALIDATE + CAP XP/coins on the SERVER too.
 *   config             overrides for XP_PER_POINT, XP_MAX_PER_PLAY, XP_PLAYS_PER_DAY,
 *                      COINS_PER_PLAY, DAILY_COIN_CAP, MIN_SCORE_VALID
 *   logoSrc            EAT60 logo image URL (default: embedded). Crop used: x50 y160 w412 h162 of the 512px logo.
 *   storageKey         localStorage prefix for the demo wallet (default "rr")
 * The parent must have a height. Poppins is used if your app already loads it.
 */
import { useEffect, useRef, useState } from "react";
import { playAppSound, unlockAppSounds } from "../../../lib/sounds";

const DEFAULT_LOGO = "data:image/png;base64,";
const CSS = `
.rr-root{position:relative;width:100%;height:100%;overflow:hidden;background:#171717;color:#fff;font-family:Poppins,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;touch-action:none;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}
.rr-root canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.rr-hud{position:absolute;top:calc(10px + env(safe-area-inset-top,0px));left:12px;right:12px;display:flex;gap:8px;align-items:center;pointer-events:none}
.rr-chip{padding:6px 10px;border-radius:16px;background:rgba(23,23,23,.7);border:1px solid rgba(166,255,77,.35);backdrop-filter:blur(6px);font-size:11px}
.rr-chip b{display:inline-block;font-size:18px;margin-left:5px}
.rr-bump{animation:rrbump .3s ease-out}
@keyframes rrbump{50%{transform:scale(1.4);color:#a6ff4d}}
.rr-fs{pointer-events:auto;margin-left:auto;width:38px;height:38px;border-radius:14px;border:1px solid rgba(166,255,77,.35);background:rgba(23,23,23,.7);color:#fff;font-size:18px;padding:0;cursor:pointer}
.rr-ov{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(10,10,12,.65);backdrop-filter:blur(6px);opacity:0;pointer-events:none;transition:opacity .35s}
.rr-ov.show{opacity:1;pointer-events:auto}
.rr-card{width:min(88%,350px);text-align:center;padding:22px 22px 24px;border-radius:26px;background:#1f1f22;border:1px solid rgba(166,255,77,.4);box-shadow:0 0 40px rgba(166,255,77,.12);transform:translateY(24px) scale(.92);transition:transform .45s cubic-bezier(.2,1.4,.4,1)}
.show .rr-card{transform:none}
.rr-lg{position:relative;width:240px;height:94px;overflow:hidden;margin:0 auto 10px;border-radius:12px;background:#171717}
.rr-lg img{position:absolute;width:298px;left:-29px;top:-93px}
.rr-card h1{margin:4px 0;font-size:26px;font-weight:800}
.rr-card p{margin:0 0 14px;opacity:.8;font-size:13px;line-height:1.5}
.rr-rw{margin:-4px 0 14px;font-size:15px;line-height:1.8;font-weight:600}.rr-rw .tot{opacity:.75;font-size:12px}.rr-rw .nt{color:#a6ff4d;font-size:12px}
.rr-go{border:0;border-radius:18px;padding:13px 32px;font:800 16px Poppins,system-ui,sans-serif;color:#171717;background:#a6ff4d;box-shadow:0 8px 24px rgba(166,255,77,.35);animation:rrpulse 1.6s ease-in-out infinite;cursor:pointer}
@keyframes rrpulse{50%{transform:scale(1.06)}}
`;

export default function RiderRush({ logoSrc = DEFAULT_LOGO, config, onGameEnd, storageKey = "rr", className = "", style }) {
  const cvRef = useRef(null), rootRef = useRef(null), startRef = useRef(() => {}), endRef = useRef(onGameEnd);
  endRef.current = onGameEnd;
  const [score, setScore] = useState(0), [lives, setLives] = useState(3), [coins, setCoins] = useState(0);
  const [ui, setUi] = useState({ show: true, title: "Rider Rush", text: "Ride through Ballia and pick up orders. Swipe or tap left / right to change lane. Dodge cars, cows and barricades!", r: null, tot: null, btn: "Start delivery" });

  useEffect(() => {

const cv=cvRef.current,ctx=cv.getContext('2d');
const timers=[];let raf=0;
const logo=new Image();logo.src=logoSrc;
// ===== GAME CONFIG (tune these) =====
const CFG={XP_PER_POINT:3,XP_MAX_PER_PLAY:60,XP_PLAYS_PER_DAY:7,COINS_PER_PLAY:25,DAILY_COIN_CAP:200,MIN_SCORE_VALID:5,...(config||{})};
const KEYW=storageKey+'_wallet',KEYB=storageKey+'_best';
const OUT=[{n:'The Pizza Galaxy',c:'#6a3dff',e:'🍕'},{n:'Cheesy Town',c:'#f5a300',e:'🧀'},{n:'Wok Story',c:'#d8322b',e:'🥡'},{n:'The Red Oven',c:'#b3201f',e:'🥖'},{n:'Gaon Rasoi',c:'#7a5230',e:'🍛'},{n:'Wrap n Roll',c:'#3c9a45',e:'🌯'},{n:'Urban Thali',c:'#0f8a82',e:'🍱'}];
const ZONES=['Station Road','Harpur','Bhirgu Ashram','Middhi','Tikhampur','Japlinganj'];
const TEMPLES=['Bhrigu Mandir','Baleshwar Mandir'];
const todayKey=()=>{const d=new Date();return d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate()};
let wallet={xp:0,coins:0,day:'',plays:0,xpPlays:0,coinsToday:0},best=0;
try{Object.assign(wallet,JSON.parse(localStorage.getItem(KEYW)||'{}'));best=+localStorage.getItem(KEYB)||0}catch(e){}
function saveWallet(){try{localStorage.setItem(KEYW,JSON.stringify(wallet))}catch(e){}}
// XP + coin rules in ONE place
function settle(score){
  if(wallet.day!==todayKey()){wallet.day=todayKey();wallet.plays=0;wallet.xpPlays=0;wallet.coinsToday=0}
  const r={score,xp:0,coins:0,note:''};
  if(score>=CFG.MIN_SCORE_VALID){
    wallet.plays++;
    if(wallet.xpPlays<CFG.XP_PLAYS_PER_DAY){r.xp=Math.min(CFG.XP_MAX_PER_PLAY,score*CFG.XP_PER_POINT);wallet.xpPlays++}
    else r.note='Daily XP limit reached';
    r.coins=Math.min(CFG.COINS_PER_PLAY,Math.max(0,CFG.DAILY_COIN_CAP-wallet.coinsToday));
    if(!r.coins)r.note=(r.note?r.note+' · ':'')+'Daily coin cap reached';
    wallet.xp+=r.xp;wallet.coins+=r.coins;wallet.coinsToday+=r.coins;
  }else r.note='Deliver '+CFG.MIN_SCORE_VALID+'+ orders to earn rewards';
  saveWallet();return r;
}
setCoins(wallet.coins);

const RS=.6,LIME='#a6ff4d',EF='"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",serif',K=.006,ZMAX=1200,ZLEN=4500;
const HC=['#3b3550','#4a3b4f','#2f3d52','#42364a'],CC=['#e53935','#1e88e5','#fdd835','#f2f2f2'];
let W,H,u,HZ,YR,LW,sb;
const S=z=>1/(1+z*K),Y=s=>HZ+(YR-HZ)*s;
let state='ready',t=0,dist=0,v=0,lanePos=1,target=1,lives=3,score=0,inv=0,shake=0,wob=0,deadT=0,items=[],side=[],parts=[],pops=[],toast=null,lastZone=-1,nextRow=0,gap=300,nextSide=[0,0],nextTemple=2600,tempN=0,why='';
const stars=Array.from({length:40},()=>({x:Math.random(),y:Math.random()*.9,r:Math.random()*1.4+.4}));
const sky=Array.from({length:30},(_,i)=>({x:i/30,w:.05+Math.random()*.03,h:.03+Math.random()*.08}));
function resize(){const d=Math.min(devicePixelRatio||1,2);W=cv.clientWidth;H=cv.clientHeight;cv.width=W*d;cv.height=H*d;ctx.setTransform(d,0,0,d,0,0);HZ=H*.34;YR=H*.82;LW=Math.min(W*.27,H*.2);sb=(H-HZ)/(YR-HZ);u=Math.max(.7,Math.min(1.05,Math.min(W/390,H/760)))}
function hud(){setLives(Math.max(0,lives))}
function reset(){dist=0;v=360;lanePos=1;target=1;lives=3;score=0;inv=0;shake=0;wob=0;deadT=0;items=[];side=[];parts=[];pops=[];toast=null;lastZone=-1;nextRow=800;gap=300;nextSide=[300,420];nextTemple=2600;tempN=0;why='';setScore(0);hud()}
function burst(x,y,n,cols){for(let i=0;i<n;i++){const a=Math.random()*6.283,s=60+Math.random()*180;parts.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s-60,l:1,c:cols[i%cols.length],r:2+Math.random()*3})}}
function spawn(){
  const far=dist+ZMAX+60,KS=['car','car','cow','barr','barr'];
  while(nextRow<far){
    const ln=[0,1,2].sort(()=>Math.random()-.5),nb=dist>3000&&Math.random()<.5?2:1;
    for(let i=0;i<nb;i++)items.push({p:nextRow,l:ln[i],k:KS[Math.random()*5|0],c:CC[Math.random()*4|0]});
    gap=Math.max(280,v*.62);
    if(Math.random()<.75)items.push({p:nextRow+gap/2,l:Math.random()*3|0,k:'order',o:OUT[Math.random()*OUT.length|0]});
    nextRow+=gap;
  }
  for(let sd=0;sd<2;sd++)while(nextSide[sd]<far){
    const p=nextSide[sd],r=Math.random(),o={p,s:sd?1:-1,h:110+(p%70|0),c:HC[Math.random()*4|0]};
    if(p>=nextTemple){o.k='temple';o.name=TEMPLES[tempN++%2];nextTemple+=3200}
    else if(r<.45){o.k='shop';o.o=OUT[Math.random()*OUT.length|0]}
    else if(r<.7)o.k='house';
    else if(r<.82){o.k='sign';o.name=ZONES[Math.floor(p/ZLEN)%ZONES.length]}
    else o.k='tree';
    side.push(o);nextSide[sd]+=150+Math.random()*90;
  }
}
function crash(){
  playAppSound('riderCrash');
  state='dead';deadT=0;shake=.6;burst(W/2+(lanePos-1)*LW,YR-60*u,24,[LIME,'#fff','#ff9a3c']);
  try{navigator.vibrate&&navigator.vibrate([60,40,90])}catch(e){}
  if(score>best){best=score;try{localStorage.setItem(KEYB,best)}catch(e){}}
  const r=settle(score),meters=dist/10|0;setCoins(wallet.coins);
  if(r.coins>0)playAppSound('coinCollect',0.65);
  // Host app hook: save the result to your backend (e.g. Supabase) and validate / cap it on the SERVER too.
  if(endRef.current)try{endRef.current({score,distance:meters,xp:r.xp,coins:r.coins,note:r.note,totals:{xp:wallet.xp,coins:wallet.coins}})}catch(e){}
  const ttl={car:'Crashed! 🚗',cow:'Cow on the road! 🐄',barr:'Barricade! 🚧'}[why]||'Crashed!';
  timers.push(setTimeout(()=>setUi({show:true,title:ttl,text:'Orders '+score+'  ·  '+meters+' m  ·  Best '+best,r,tot:{xp:wallet.xp,coins:wallet.coins},btn:'Ride again'}),1000));
}
function advance(dt){dist+=v*dt;lanePos+=(target-lanePos)*Math.min(1,dt*11);spawn()}
function play(dt){
  v=Math.min(720,360+dist/35);advance(dt);
  const zi=Math.floor(dist/ZLEN)%ZONES.length;if(zi!==lastZone){lastZone=zi;toast={s:'📍 '+ZONES[zi],t:0}}
  for(const it of items){
    const z=it.p-dist;if(it.done||z>45||z<-45||Math.abs(lanePos-it.l)>.62)continue;
    const px=W/2+(lanePos-1)*LW;
    if(it.k==='order'){
      it.done=true;score++;setScore(score);
      pops.push({x:px,y:YR-150*u,t:0,s:'+1 '+it.o.n});burst(px,YR-95*u,14,[LIME,'#fff','#ffd25a']);
      try{navigator.vibrate&&navigator.vibrate(15)}catch(e){}
    }else if(inv<=0){
      it.done=true;why=it.k;lives--;inv=1.6;shake=.4;wob=.5;hud();burst(px,YR-60*u,12,['#ff9a3c','#fff']);
      if(lives>0)playAppSound('gameHit',0.65);
      try{navigator.vibrate&&navigator.vibrate(50)}catch(e){}
      if(lives<=0)return crash();
    }
  }
  items=items.filter(it=>it.p-dist>-80&&!(it.done&&it.k==='order'));side=side.filter(o=>o.p-dist>-150);
}
// ---- drawing helpers
const poly=(pts,c)=>{ctx.fillStyle=c;ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.fill()};
const rr=(x,y,w,h,r,c)=>{ctx.fillStyle=c;ctx.beginPath();ctx.roundRect?ctx.roundRect(x,y,w,h,r):ctx.rect(x,y,w,h);ctx.fill()};
const emo=(e,x,y,sz)=>{ctx.font=sz+'px '+EF;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillStyle='#fff';ctx.fillText(e,x,y)};
const ln=(x1,y1,x2,y2,w,c)=>{ctx.strokeStyle=c;ctx.lineWidth=w;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke()};
function drawBg(){
  const g=ctx.createLinearGradient(0,0,0,HZ);g.addColorStop(0,'#0e0a22');g.addColorStop(.6,'#3a1850');g.addColorStop(1,'#ff8a3c');ctx.fillStyle=g;ctx.fillRect(0,0,W,HZ+1);
  for(const s of stars){ctx.fillStyle=`rgba(255,255,255,${.4+.4*Math.sin(t*2+s.x*20)})`;ctx.fillRect(s.x*W,s.y*HZ*.7,s.r,s.r)}
  const rg=ctx.createRadialGradient(W/2,HZ,0,W/2,HZ,W*.6);rg.addColorStop(0,'rgba(255,190,90,.55)');rg.addColorStop(1,'rgba(255,190,90,0)');ctx.fillStyle=rg;ctx.fillRect(0,0,W,HZ+2);
  ctx.fillStyle='#1a1030';for(const b of sky)ctx.fillRect(b.x*W,HZ-b.h*H,b.w*W,b.h*H+1);
  ctx.fillStyle='#14131c';ctx.fillRect(0,HZ,W,H-HZ);
  for(const sd of [-1,1])poly([[W/2,HZ],[W/2+sd*1.5*LW*sb,H],[W/2+sd*2*LW*sb,H]],'#34323f');
  poly([[W/2,HZ],[W/2-1.5*LW*sb,H],[W/2+1.5*LW*sb,H]],'#24232d');
  for(const sd of [-1,1])ln(W/2,HZ,W/2+sd*1.5*LW*sb,H,3,'rgba(240,240,240,.85)');
  const off=dist%140;ctx.fillStyle='rgba(240,240,240,.7)';
  for(const sd of [-.5,.5])for(let z=-off-140;z<ZMAX;z+=140){
    const z0=Math.max(z,-60),z1=z+60;if(z1<-60)continue;const s0=S(z0),s1=S(z1);
    poly([[W/2+sd*LW*s0-3*s0,Y(s0)],[W/2+sd*LW*s0+3*s0,Y(s0)],[W/2+sd*LW*s1+3*s1,Y(s1)],[W/2+sd*LW*s1-3*s1,Y(s1)]],'rgba(240,240,240,.7)');
  }
  if(v>500){ctx.strokeStyle='rgba(255,255,255,.12)';ctx.lineWidth=2;for(let i=0;i<10;i++){const a=(i/10)*Math.PI+.1+((t*.7+i)%1)*.05,r=H*.25+((t*2+i*.37)%1)*H*.55;ctx.beginPath();ctx.moveTo(W/2+Math.cos(a)*r*.5,HZ+Math.abs(Math.sin(a))*r*.5);ctx.lineTo(W/2+Math.cos(a)*r,HZ+Math.abs(Math.sin(a))*r);ctx.stroke()}}
}
function drawSide(o){
  const z=o.p-dist;if(z>ZMAX||z<-20)return;const s=S(z),gy=Y(s),sd=o.s,bx=W/2+sd*2*LW*s;
  ctx.globalAlpha=z>ZMAX-300?(ZMAX-z)/300:1;
  const R=(x,y,w,h,c)=>{ctx.fillStyle=c;ctx.fillRect(sd>0?bx+x*s:bx-(x+w)*s,gy-(y+h)*s,w*s,h*s)};
  const T=(tx,x,y,sz,c)=>{const f=sz*u*s;if(f<5)return;ctx.font=`800 ${f}px Poppins,system-ui,sans-serif`;ctx.fillStyle=c;ctx.textAlign='center';ctx.textBaseline='alphabetic';ctx.fillText(tx,bx+sd*x*s,gy-y*s)};
  const X=x=>bx+sd*x*s,Yy=y=>gy-y*s;
  if(o.k==='shop'){
    R(0,0,170,200,'#1f1c2a');R(0,150,170,50,o.o.c);T(o.o.n,85,168,17,'#fff');
    R(0,118,170,22,'#f4efe6');for(let i=0;i<5;i++)R(i*34,118,17,22,o.o.c);
    R(16,10,62,92,'#ffd98a');R(98,10,56,92,'#2b2838');emo(o.o.e,X(126),Yy(60),38*u*s);
  }else if(o.k==='house'){
    R(0,0,150,o.h,o.c);R(0,o.h,150,8,'#555');for(let i=0;i<3;i++)R(14+i*46,o.h-60,30,34,Math.sin(o.p+i)>0?'#ffd98a':'#1a1826');
  }else if(o.k==='tree'){
    R(24,0,12,52,'#4a2f1c');ctx.fillStyle='#1f6b3a';ctx.beginPath();ctx.arc(X(30),Yy(90),42*s,0,6.3);ctx.fill();
  }else if(o.k==='sign'){
    R(54,0,6,100,'#999');R(0,100,120,44,'#fff');R(4,104,112,36,'#0f7a45');T(o.name,60,114,15,'#fff');
  }else{
    R(0,0,210,46,'#d9c3a3');R(18,46,174,36,'#e8d5b5');
    poly([[X(55),Yy(82)],[X(155),Yy(82)],[X(135),Yy(170)],[X(117),Yy(236)],[X(105),Yy(270)],[X(93),Yy(236)],[X(75),Yy(170)]],'#f28c28');
    R(103,270,3,40,'#fff');R(106,292,28,16,'#ff7a00');R(30,52,150,26,'#2a1a0a');T(o.name,105,58,15,'#ffd25a');
    const gl=ctx.createRadialGradient(X(105),Yy(150),0,X(105),Yy(150),120*s);gl.addColorStop(0,'rgba(255,200,90,.3)');gl.addColorStop(1,'rgba(255,200,90,0)');ctx.fillStyle=gl;ctx.fillRect(X(105)-120*s,Yy(150)-120*s,240*s,240*s);
  }
  ctx.globalAlpha=1;
}
function drawItem(it){
  const z=it.p-dist;if(z>ZMAX||z<-60||(it.done&&it.k==='order'))return;
  const s=S(z),x=W/2+(it.l-1)*LW*s,y=Y(s),q=s*u;
  ctx.globalAlpha=z>ZMAX-300?(ZMAX-z)/300:z<-30?Math.max(0,(z+60)/30):1;
  ctx.fillStyle='rgba(0,0,0,.35)';ctx.beginPath();ctx.ellipse(x,y,38*q,8*q,0,0,6.3);ctx.fill();
  if(it.k==='car'){
    rr(x-26*q,y-84*q,52*q,34*q,10*q,it.c);rr(x-34*q,y-58*q,68*q,46*q,9*q,it.c);rr(x-20*q,y-80*q,40*q,20*q,6*q,'#1c2733');
    rr(x-32*q,y-40*q,14*q,9*q,3*q,'#ff3030');rr(x+18*q,y-40*q,14*q,9*q,3*q,'#ff3030');rr(x-36*q,y-14*q,14*q,14*q,4*q,'#111');rr(x+22*q,y-14*q,14*q,14*q,4*q,'#111');
  }else if(it.k==='cow')emo('🐄',x,y-34*q,96*q);
  else if(it.k==='barr'){
    rr(x-34*q,y-26*q,6*q,26*q,2*q,'#555');rr(x+28*q,y-26*q,6*q,26*q,2*q,'#555');rr(x-40*q,y-52*q,80*q,26*q,4*q,'#fff');
    for(let i=0;i<4;i++)rr(x-40*q+i*20*q,y-52*q,10*q,26*q,2*q,'#e53935');
  }else{
    const yy=y-56*q+Math.sin(t*5+it.p)*4*q,g=ctx.createRadialGradient(x,yy,0,x,yy,52*q);g.addColorStop(0,'rgba(166,255,77,.6)');g.addColorStop(1,'rgba(166,255,77,0)');
    ctx.fillStyle=g;ctx.fillRect(x-52*q,yy-52*q,104*q,104*q);
    ctx.fillStyle='#171717';ctx.strokeStyle=LIME;ctx.lineWidth=3*q;ctx.beginPath();ctx.arc(x,yy,28*q,0,6.3);ctx.fill();ctx.stroke();emo(it.o.e,x,yy+2*q,32*q);
  }
  ctx.globalAlpha=1;
}
function drawRider(){
  const x=W/2+(lanePos-1)*LW,lean=Math.max(-.35,Math.min(.35,(target-lanePos)*.32))+Math.sin(t*45)*wob*.06;
  ctx.save();ctx.translate(x,YR);ctx.scale(u*RS,u*RS);ctx.rotate(state==='dead'?Math.min(1.5,deadT*3):lean);
  if(inv>0&&state==='play')ctx.globalAlpha=Math.sin(t*40)>0?1:.35;
  ctx.fillStyle='rgba(0,0,0,.4)';ctx.beginPath();ctx.ellipse(0,2,46,9,0,0,6.3);ctx.fill();
  rr(-12,-42,24,42,9,'#0c0c0c');ctx.fillStyle='#3a3a3a';for(let i=0;i<4;i++)ctx.fillRect(-12,-40+((t*v/7+i*10)%40),24,3);
  rr(-26,-68,52,32,13,'#2b2b34');rr(-16,-55,32,7,3,'#ff3b3b');
  ln(-17,-84,-30,-46,16,'#26334d');ln(17,-84,30,-46,16,'#26334d');rr(-40,-50,18,11,5,'#111');rr(22,-50,18,11,5,'#111');
  ln(-40,-142,-53,-102,13,'#2b2b34');ln(40,-142,53,-102,13,'#2b2b34');ctx.fillStyle=LIME;ctx.beginPath();ctx.arc(-53,-98,8,0,6.3);ctx.arc(53,-98,8,0,6.3);ctx.fill();
  ctx.fillStyle=LIME;ctx.beginPath();ctx.arc(0,-192,22,0,6.3);ctx.fill();rr(-4,-214,8,40,3,'#171717');ctx.fillStyle='rgba(255,255,255,.5)';ctx.beginPath();ctx.ellipse(-10,-200,5,9,.5,0,6.3);ctx.fill();
  rr(-47,-176,94,96,14,'#171717');ctx.strokeStyle=LIME;ctx.lineWidth=3;ctx.beginPath();ctx.roundRect?ctx.roundRect(-47,-176,94,96,14):ctx.rect(-47,-176,94,96);ctx.stroke();
  rr(-47,-176,94,15,10,LIME);
  if(logo.complete&&logo.naturalWidth)ctx.drawImage(logo,50,160,412,162,-41,-150,82,32);
  else{ctx.font='800 24px Poppins,sans-serif';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText('EAT',-14,-126);ctx.fillStyle=LIME;ctx.fillText('60',24,-126)}
  rr(-47,-104,94,5,2,'rgba(166,255,77,.7)');
  ctx.restore();
}
function draw(){
  ctx.save();if(shake>0)ctx.translate((Math.random()-.5)*12*shake*2,(Math.random()-.5)*12*shake*2);
  drawBg();
  const list=[...side.map(o=>[o.p,0,o]),...items.map(o=>[o.p,1,o])].sort((a,b)=>b[0]-a[0]);let rd=false;
  for(const [p,k,o] of list){if(!rd&&p<dist){drawRider();rd=true}k?drawItem(o):drawSide(o)}
  if(!rd)drawRider();
  for(const p of parts){ctx.globalAlpha=Math.max(0,p.l);ctx.fillStyle=p.c;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,6.3);ctx.fill()}
  ctx.globalAlpha=1;ctx.textAlign='center';ctx.textBaseline='alphabetic';
  ctx.font='800 17px Poppins,system-ui,sans-serif';
  for(const p of pops){ctx.globalAlpha=Math.max(0,1-p.t/1);ctx.fillStyle=LIME;ctx.fillText(p.s,p.x,p.y-p.t*50)}
  ctx.globalAlpha=1;ctx.font='600 13px Poppins,system-ui,sans-serif';ctx.fillStyle='rgba(255,255,255,.85)';ctx.fillText((dist/10|0)+' m',W/2,70);
  if(toast){const a=Math.sin(Math.min(1,toast.t/2.2)*Math.PI);ctx.globalAlpha=a;ctx.font='800 26px Poppins,system-ui,sans-serif';ctx.fillStyle='#fff';ctx.strokeStyle='rgba(0,0,0,.5)';ctx.lineWidth=5;ctx.strokeText(toast.s,W/2,H*.2);ctx.fillText(toast.s,W/2,H*.2);ctx.globalAlpha=1}
  ctx.restore();
}
let last=0;
function loop(ts){
  const dt=Math.min(.033,(ts-last)/1000||0);last=ts;t+=dt;
  if(state==='play')play(dt);
  else if(state==='ready'){v=150;advance(dt)}
  else{deadT+=dt;v=Math.max(0,v-1000*dt);dist+=v*dt}
  inv=Math.max(0,inv-dt);shake=Math.max(0,shake-dt);wob=Math.max(0,wob-dt);
  for(const p of parts){p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=300*dt;p.l-=dt*1.6}parts=parts.filter(p=>p.l>0);
  for(const p of pops)p.t+=dt;pops=pops.filter(p=>p.t<1);
  if(toast){toast.t+=dt;if(toast.t>2.2)toast=null}
  draw();raf=requestAnimationFrame(loop);
}
// input
const go=d=>{if(state==='play')target=Math.max(0,Math.min(2,target+d))};
let sx=null,mv=false;
const pd=e=>{sx=e.clientX;mv=false},pm=e=>{if(sx==null)return;const d=e.clientX-sx;if(Math.abs(d)>28){go(d>0?1:-1);sx=e.clientX;mv=true}},pu=e=>{if(sx!=null&&!mv)go(e.clientX>W/2?1:-1);sx=null},kd=e=>{if(e.key==='ArrowLeft'||e.key==='a')go(-1);else if(e.key==='ArrowRight'||e.key==='d')go(1)};
cv.addEventListener('pointerdown',pd);cv.addEventListener('pointermove',pm);window.addEventListener('pointerup',pu);window.addEventListener('keydown',kd);
const ro=new ResizeObserver(resize);ro.observe(cv);
startRef.current=()=>{unlockAppSounds(['announced','riderCrash','coinCollect','gameHit']);setUi(p=>({...p,show:false}));resize();reset();state='play'};
resize();reset();raf=requestAnimationFrame(loop);
return()=>{cancelAnimationFrame(raf);timers.forEach(clearTimeout);cv.removeEventListener('pointerdown',pd);cv.removeEventListener('pointermove',pm);window.removeEventListener('pointerup',pu);window.removeEventListener('keydown',kd);ro.disconnect()};

    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const toggleFs = () => { try { (document.fullscreenElement ? document.exitFullscreen() : rootRef.current.requestFullscreen()).catch(() => {}); } catch (e) {} };
  const canFs = typeof document !== "undefined" && !!document.documentElement.requestFullscreen;

  return (
    <div ref={rootRef} className={"rr-root " + className} style={style}>
      <style>{CSS}</style>
      <canvas ref={cvRef} />
      <div className="rr-hud">
        <div className="rr-chip">Orders<b key={score} className="rr-bump">{score}</b></div>
        <div className="rr-chip">Life<b style={{ fontSize: 13 }}>{"❤️".repeat(lives) || "💔"}</b></div>
        <div className="rr-chip">🪙<b>{coins}</b></div>
        {canFs && <button className="rr-fs" aria-label="Fullscreen" onClick={toggleFs}>⛶</button>}
      </div>
      <div className={"rr-ov" + (ui.show ? " show" : "")}>
        <div className="rr-card">
          <div className="rr-lg"><img src={logoSrc} alt="EAT60" /></div>
          <h1>{ui.title}</h1>
          <p>{ui.text}</p>
          {ui.r && (
            <div className="rr-rw">
              {(ui.r.xp || ui.r.coins) ? <div>⭐ +{ui.r.xp} XP · 🪙 +{ui.r.coins}</div> : null}
              <div className="tot">Total ⭐ {ui.tot.xp} · 🪙 {ui.tot.coins}</div>
              {ui.r.note && <div className="nt">{ui.r.note}</div>}
            </div>
          )}
          <button className="rr-go" onClick={() => startRef.current()}>{ui.btn}</button>
        </div>
      </div>
    </div>
  );
}
